const i=JSON.parse('{"workId":"li-ji","chapter":{"id":"li-ji_ch-24","workId":"li-ji","order":24,"title":"祭義","difficulty":4,"estimatedMinutes":15,"passageIds":["li-ji_ch-24_p-1","li-ji_ch-24_p-2","li-ji_ch-24_p-3","li-ji_ch-24_p-4","li-ji_ch-24_p-5","li-ji_ch-24_p-6","li-ji_ch-24_p-7","li-ji_ch-24_p-8","li-ji_ch-24_p-9","li-ji_ch-24_p-10","li-ji_ch-24_p-11","li-ji_ch-24_p-12","li-ji_ch-24_p-13","li-ji_ch-24_p-14","li-ji_ch-24_p-15","li-ji_ch-24_p-16","li-ji_ch-24_p-17","li-ji_ch-24_p-18","li-ji_ch-24_p-19","li-ji_ch-24_p-20","li-ji_ch-24_p-21","li-ji_ch-24_p-22","li-ji_ch-24_p-23","li-ji_ch-24_p-24","li-ji_ch-24_p-25","li-ji_ch-24_p-26","li-ji_ch-24_p-27","li-ji_ch-24_p-28","li-ji_ch-24_p-29","li-ji_ch-24_p-30","li-ji_ch-24_p-31","li-ji_ch-24_p-32","li-ji_ch-24_p-33","li-ji_ch-24_p-34","li-ji_ch-24_p-35","li-ji_ch-24_p-36","li-ji_ch-24_p-37","li-ji_ch-24_p-38","li-ji_ch-24_p-39","li-ji_ch-24_p-40","li-ji_ch-24_p-41","li-ji_ch-24_p-42","li-ji_ch-24_p-43","li-ji_ch-24_p-44","li-ji_ch-24_p-45","li-ji_ch-24_p-46","li-ji_ch-24_p-47"],"tags":["儒家","禮樂"]},"passages":[{"id":"li-ji_ch-24_p-1","chapterId":"li-ji_ch-24","order":1,"canonicalText":"祭不欲數，數則煩，煩則不敬。祭不欲疏，疏則怠，怠則忘。是故君子合諸天道：春禘秋嘗。霜露既降，君子履之，必有悽愴之心，非其寒之謂也。春，雨露既濡，君子履之，必有怵惕之心，如將見之。樂以迎來，哀以送往，故禘有樂而嘗無樂。","sentenceIds":["li-ji_ch-24_p-1_s-1","li-ji_ch-24_p-1_s-2","li-ji_ch-24_p-1_s-3","li-ji_ch-24_p-1_s-4","li-ji_ch-24_p-1_s-5","li-ji_ch-24_p-1_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"祭不欲數，數則煩，煩則不敬。祭不欲疏，疏則怠，怠則忘。正因為如此具有道德修養之君子賢士人階層合諸天道：春禘秋嘗。霜露既降，具有道德修養之君子賢士人階層履的，必有悽愴的心，絕不是他的寒的謂啊。春，雨露既濡，具有道德修養之君子賢士人階層履的，必有怵惕的心，如將見的。雅樂和聲與心靈感化以迎來，哀以送往，所以禘有雅樂和聲與心靈感化而且嘗無雅樂和聲與心靈感化。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 1 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「祭不欲數，數則煩，煩則不敬」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「祭不欲數，數則煩，煩則不敬。祭不欲疏，疏則怠，怠則忘……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-2","chapterId":"li-ji_ch-24","order":2,"canonicalText":"致齊於內，散齊於外。齊之日：思其居處，思其笑語，思其志意，思其所樂，思其所嗜。齊三日，乃見其所為齊者。","sentenceIds":["li-ji_ch-24_p-2_s-1","li-ji_ch-24_p-2_s-2","li-ji_ch-24_p-2_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"致齊於內，散齊於外。齊的日：思他的居處，思他的笑語，思他的志意，思他的所雅樂和聲與心靈感化，思他的所嗜。齊三日，乃見他的所為齊的人或禮儀規程與道崇高德行與品性修養規範制規範。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 2 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「致齊於內，散齊於外」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「致齊於內，散齊於外。齊之日：思其居處，思其笑語，思其……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-3","chapterId":"li-ji_ch-24","order":3,"canonicalText":"祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞乎其容聲，出戶而聽，愾然必有聞乎其嘆息之聲。","sentenceIds":["li-ji_ch-24_p-3_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"祭的日：入室，僾然必有見乎他的位，周還出戶，肅然必有聞乎他的容聲，出戶而且聽，愾然必有聞乎他的嘆息的聲。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 3 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞乎其容聲，出戶而聽，愾然必有聞乎其嘆息之聲」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-4","chapterId":"li-ji_ch-24","order":4,"canonicalText":"是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜慾不忘乎心。致愛則存，致愨則著。著存不忘乎心，夫安得不敬乎？","sentenceIds":["li-ji_ch-24_p-4_s-1","li-ji_ch-24_p-4_s-2","li-ji_ch-24_p-4_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"正因為如此，先王的孝啊，色不忘乎目，聲不絕乎耳，心志嗜慾不忘乎心。致愛則存，致愨則著。著存不忘乎心，夫安得不敬乎？","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 4 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜慾不忘乎心」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜慾不……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-5","chapterId":"li-ji_ch-24","order":5,"canonicalText":"君子生則敬養，死則敬享，思終身弗辱也。君子有終身之喪，忌日之謂也。忌日不用，非不祥也。言夫日，志有所至，而不敢盡其私也。","sentenceIds":["li-ji_ch-24_p-5_s-1","li-ji_ch-24_p-5_s-2","li-ji_ch-24_p-5_s-3","li-ji_ch-24_p-5_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"具有道德修養之君子賢士人階層生則敬養，死則敬享，思終身弗辱啊。具有道德修養之君子賢士人階層有終身的喪，忌日的謂啊。忌日不用，絕不是不祥啊。言夫日，志有所至，而且不敢盡他的私啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 5 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君子生則敬養，死則敬享，思終身弗辱也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君子生則敬養，死則敬享，思終身弗辱也。君子有終身之喪……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-6","chapterId":"li-ji_ch-24","order":6,"canonicalText":"唯聖人為能饗帝，孝子為能饗親。饗者，鄉也。鄉之，然後能饗焉。是故孝子臨屍而不怍。君牽牲，夫人奠盎。君獻屍，夫人薦豆。卿大夫相君，命婦相夫人。齊齊乎其敬也，愉愉乎其忠也，勿勿諸其欲其饗之也。","sentenceIds":["li-ji_ch-24_p-6_s-1","li-ji_ch-24_p-6_s-2","li-ji_ch-24_p-6_s-3","li-ji_ch-24_p-6_s-4","li-ji_ch-24_p-6_s-5","li-ji_ch-24_p-6_s-6","li-ji_ch-24_p-6_s-7","li-ji_ch-24_p-6_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"唯聖人為能饗帝，孝子為能饗親。饗的人或禮儀規程與道崇高德行與品性修養規範制規範，鄉啊。鄉的，然後能饗焉。正因為如此孝子臨屍而且不怍。君牽牲，夫人奠盎。君獻屍，夫人薦豆。卿卿大夫貴族官員相君，命婦相夫人。齊齊乎他的敬啊，愉愉乎他的忠啊，勿勿諸他的欲他的饗的啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 6 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「唯聖人為能饗帝，孝子為能饗親」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「唯聖人為能饗帝，孝子為能饗親。饗者，鄉也。鄉之，然後……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-7","chapterId":"li-ji_ch-24","order":7,"canonicalText":"文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，稱諱如見親。祀之忠也，如見親之所愛，如欲色然；其文王與？《詩》雲：「明發不寐，有懷二人。」文王之詩也。祭之明日，明發不寐，饗而致之，又從而思之。祭之日，樂與哀半；饗之必樂，已至必哀。","sentenceIds":["li-ji_ch-24_p-7_s-1","li-ji_ch-24_p-7_s-2","li-ji_ch-24_p-7_s-3","li-ji_ch-24_p-7_s-4","li-ji_ch-24_p-7_s-5","li-ji_ch-24_p-7_s-6","li-ji_ch-24_p-7_s-7","li-ji_ch-24_p-7_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"文王的祭啊：事死的人或禮儀規程與道崇高德行與品性修養規範制規範如事生，思死的人或禮儀規程與道崇高德行與品性修養規範制規範如不欲生，忌日必哀，稱諱如見親。祀的忠啊，如見親的所愛，如欲色然；他的文王與？《詩》雲：「明發不寐，有懷二人。」文王的詩啊。祭的明日，明發不寐，饗而且致的，又從而且思的。祭的日，雅樂和聲與心靈感化與哀半；饗的必雅樂和聲與心靈感化，已至必哀。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 7 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，稱諱如見親」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-8","chapterId":"li-ji_ch-24","order":8,"canonicalText":"仲尼嘗，奉薦而進其親也愨，其行趨趨以數。已祭，子贛問曰：「子之言祭，濟濟漆漆然；今子之祭，無濟濟漆漆，何也？」","sentenceIds":["li-ji_ch-24_p-8_s-1","li-ji_ch-24_p-8_s-2","li-ji_ch-24_p-8_s-3","li-ji_ch-24_p-8_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲尼嘗，奉薦而且進他的親啊愨，他的行趨趨以數。已祭，子贛問說道：「子的言祭，濟濟漆漆然；今子的祭，無濟濟漆漆，何啊？」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 8 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲尼嘗，奉薦而進其親也愨，其行趨趨以數」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲尼嘗，奉薦而進其親也愨，其行趨趨以數。已祭，子贛問……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-9","chapterId":"li-ji_ch-24","order":9,"canonicalText":"子曰：「濟濟者，容也遠也；漆漆者，容也自反也。容以遠，若容以自反也，夫何神明之及交，夫何濟濟漆漆之有乎？反饋，樂成，薦其薦俎，序其禮樂，備其百官。君子致其濟濟漆漆，夫何慌惚之有乎？夫言，豈一端而已？夫各有所當也。」","sentenceIds":["li-ji_ch-24_p-9_s-1","li-ji_ch-24_p-9_s-2","li-ji_ch-24_p-9_s-3","li-ji_ch-24_p-9_s-4","li-ji_ch-24_p-9_s-5","li-ji_ch-24_p-9_s-6","li-ji_ch-24_p-9_s-7","li-ji_ch-24_p-9_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孔子先生親自開示教導說道：「濟濟的人或禮儀規程與道崇高德行與品性修養規範制規範，容啊遠啊；漆漆的人或禮儀規程與道崇高德行與品性修養規範制規範，容啊自反啊。容以遠，若容以自反啊，夫何神明的及交，夫何濟濟漆漆的有乎？反饋，雅樂和聲與心靈感化成，薦他的薦俎，序他的禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化，備他的百官。具有道德修養之君子賢士人階層致他的濟濟漆漆，夫何慌惚的有乎？夫言，豈一端而且已？夫各有所當啊。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 9 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子曰：「濟濟者，容也遠也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子曰：「濟濟者，容也遠也；漆漆者，容也自反也。容以遠……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-10","chapterId":"li-ji_ch-24","order":10,"canonicalText":"孝子將祭，慮事不可以不豫；比時具物，不可以不備；虛中以治之。宮室既修，墻屋既設，百物既備，夫婦齊戒沐浴，盛服奉承而進之，洞洞乎，屬屬乎，如弗勝，如將失之，其孝敬之心至也與！薦其薦俎，序其禮樂，備其百官，奉承而進之。於是諭其志意，以其恍惚以與神明交，庶或饗之。「庶或饗之」，孝子之志也。","sentenceIds":["li-ji_ch-24_p-10_s-1","li-ji_ch-24_p-10_s-2","li-ji_ch-24_p-10_s-3","li-ji_ch-24_p-10_s-4","li-ji_ch-24_p-10_s-5","li-ji_ch-24_p-10_s-6","li-ji_ch-24_p-10_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝子將祭，慮事不可以不豫；比時具物，不可以不備；虛中以治的。宮室既修，墻屋既設，百物既備，夫婦齊戒沐浴，盛服奉承而且進的，洞洞乎，屬屬乎，如弗勝，如將失的，他的孝敬的心至啊與！薦他的薦俎，序他的禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化，備他的百官，奉承而且進的。於是諭他的志意，以他的恍惚以與神明交，庶或饗的。「庶或饗的」，孝子的志啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 10 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝子將祭，慮事不可以不豫」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝子將祭，慮事不可以不豫；比時具物，不可以不備；虛中……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-11","chapterId":"li-ji_ch-24","order":11,"canonicalText":"孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉，盡其禮而不過失焉。進退必敬，如親聽命，則或使之也。","sentenceIds":["li-ji_ch-24_p-11_s-1","li-ji_ch-24_p-11_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝子的祭啊，盡他的愨而且愨焉，盡他的信而且信焉，盡他的敬而且敬焉，盡他的禮儀規程與道崇高德行與品性修養規範而且不過失焉。進退必敬，如親聽命，則或使的啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 11 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉，盡其禮而不過失焉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-12","chapterId":"li-ji_ch-24","order":12,"canonicalText":"孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其薦之也敬以欲；退而立，如將受命；已徹而退，敬齊之色不絕於面。孝子之祭也，立而不詘，固也；進而不愉，疏也；薦而不欲，不愛也；退立而不如受命，敖也；已徹而退，無敬齊之色，而忘本也。如是而祭，失之矣。","sentenceIds":["li-ji_ch-24_p-12_s-1","li-ji_ch-24_p-12_s-2","li-ji_ch-24_p-12_s-3","li-ji_ch-24_p-12_s-4","li-ji_ch-24_p-12_s-5","li-ji_ch-24_p-12_s-6","li-ji_ch-24_p-12_s-7","li-ji_ch-24_p-12_s-8","li-ji_ch-24_p-12_s-9"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝子的祭，可知啊，他的立的啊敬以詘，他的進的啊敬以愉，他的薦的啊敬以欲；退而且立，如將受命；已徹而且退，敬齊的色不絕於面。孝子的祭啊，立而且不詘，固啊；進而且不愉，疏啊；薦而且不欲，不愛啊；退立而且不如受命，敖啊；已徹而且退，無敬齊的色，而且忘本啊。如是而且祭，失的矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 12 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其薦之也敬以欲」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-13","chapterId":"li-ji_ch-24","order":13,"canonicalText":"孝子之有深愛者，必有和氣；有和氣者，必有愉色；有愉色者，必有婉容。孝子如執玉，如奉盈，洞洞屬屬然，如弗勝，如將失之。嚴威儼恪，非所以事親也，成人之道也。","sentenceIds":["li-ji_ch-24_p-13_s-1","li-ji_ch-24_p-13_s-2","li-ji_ch-24_p-13_s-3","li-ji_ch-24_p-13_s-4","li-ji_ch-24_p-13_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝子的有深愛的人或禮儀規程與道崇高德行與品性修養規範制規範，必有和氣；有和氣的人或禮儀規程與道崇高德行與品性修養規範制規範，必有愉色；有愉色的人或禮儀規程與道崇高德行與品性修養規範制規範，必有婉容。孝子如執玉，如奉盈，洞洞屬屬然，如弗勝，如將失的。嚴威儼恪，絕不是所以事親啊，成人的道啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 13 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝子之有深愛者，必有和氣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝子之有深愛者，必有和氣；有和氣者，必有愉色；有愉色……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-14","chapterId":"li-ji_ch-24","order":14,"canonicalText":"先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼。此五者，先王之所以定天下也。貴有德，何為也？為其近於道也。貴貴，為其近於君也。貴老，為其近於親也。敬長，為其近於兄也。慈幼，為其近於子也。","sentenceIds":["li-ji_ch-24_p-14_s-1","li-ji_ch-24_p-14_s-2","li-ji_ch-24_p-14_s-3","li-ji_ch-24_p-14_s-4","li-ji_ch-24_p-14_s-5","li-ji_ch-24_p-14_s-6","li-ji_ch-24_p-14_s-7","li-ji_ch-24_p-14_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"先王的所以治天下的人或禮儀規程與道崇高德行與品性修養規範制規範五：貴有崇高德行與品性修養，貴貴，貴老，敬長，慈幼。此五的人或禮儀規程與道崇高德行與品性修養規範制規範，先王的所以定天下啊。貴有崇高德行與品性修養，何為啊？為他的近於道啊。貴貴，為他的近於君啊。貴老，為他的近於親啊。敬長，為他的近於兄啊。慈幼，為他的近於子啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 14 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-15","chapterId":"li-ji_ch-24","order":15,"canonicalText":"是故至孝近乎王，至弟近乎霸。至孝近乎王，雖天子，必有父；至弟近乎霸，雖諸侯，必有兄。先王之教，因而弗改，所以領天下國家也。","sentenceIds":["li-ji_ch-24_p-15_s-1","li-ji_ch-24_p-15_s-2","li-ji_ch-24_p-15_s-3","li-ji_ch-24_p-15_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"正因為如此至孝近乎王，至弟近乎霸。至孝近乎王，雖天子，必有父；至弟近乎霸，雖諸侯，必有兄。先王的教，因而且弗改，所以領天下國家啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 15 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是故至孝近乎王，至弟近乎霸」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是故至孝近乎王，至弟近乎霸。至孝近乎王，雖天子，必有……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-16","chapterId":"li-ji_ch-24","order":16,"canonicalText":"子曰：「立愛自親始，教民睦也。立教自長始，教民順也。教以慈睦，而民貴有親；教以敬長，而民貴用命。孝以事親，順以聽命，錯諸天下，無所不行。」","sentenceIds":["li-ji_ch-24_p-16_s-1","li-ji_ch-24_p-16_s-2","li-ji_ch-24_p-16_s-3","li-ji_ch-24_p-16_s-4","li-ji_ch-24_p-16_s-5","li-ji_ch-24_p-16_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孔子先生親自開示教導說道：「立愛自親始，教民睦啊。立教自長始，教民順啊。教以慈睦，而且民貴有親；教以敬長，而且民貴用命。孝以事親，順以聽命，錯諸天下，無所不行。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 16 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「子曰：「立愛自親始，教民睦也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「子曰：「立愛自親始，教民睦也。立教自長始，教民順也。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-17","chapterId":"li-ji_ch-24","order":17,"canonicalText":"郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也。","sentenceIds":["li-ji_ch-24_p-17_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"郊的祭啊，喪的人或禮儀規程與道崇高德行與品性修養規範制規範不敢哭，凶服的人或禮儀規程與道崇高德行與品性修養規範制規範不敢入國門，敬的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 17 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-18","chapterId":"li-ji_ch-24","order":18,"canonicalText":"祭之日，君牽牲，穆答君，卿大夫序從。既入廟門，麗於碑，卿大夫袒，而毛牛尚耳，鸞刀以刲，取膟菺，乃退。爓祭，祭腥而退，敬之至也。","sentenceIds":["li-ji_ch-24_p-18_s-1","li-ji_ch-24_p-18_s-2","li-ji_ch-24_p-18_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"祭的日，君牽牲，穆答君，卿卿大夫貴族官員序從。既入廟門，麗於碑，卿卿大夫貴族官員袒，而且毛牛尚耳，鸞刀以刲，取膟菺，乃退。爓祭，祭腥而且退，敬的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 18 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「祭之日，君牽牲，穆答君，卿大夫序從」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「祭之日，君牽牲，穆答君，卿大夫序從。既入廟門，麗於碑……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-19","chapterId":"li-ji_ch-24","order":19,"canonicalText":"郊之祭，大報天而主日，配以月。夏后氏祭其闇，殷人祭其陽，周人祭日，以朝及闇。祭日於壇，祭月於坎，以別幽明，以制上下。祭日於東，祭月於西，以別外內，以端其位。日出於東，月生於西。陰陽長短，終始相巡，以致天下之和。","sentenceIds":["li-ji_ch-24_p-19_s-1","li-ji_ch-24_p-19_s-2","li-ji_ch-24_p-19_s-3","li-ji_ch-24_p-19_s-4","li-ji_ch-24_p-19_s-5","li-ji_ch-24_p-19_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"郊的祭，大報天而且主日，配以月。夏后氏祭他的闇，殷人祭他的陽，周人祭日，以朝及闇。祭日於壇，祭月於坎，以別幽明，以制上下。祭日於東，祭月於西，以別外內，以端他的位。日出於東，月生於西。陰陽長短，終始相巡，以致天下的和。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 19 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「郊之祭，大報天而主日，配以月」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「郊之祭，大報天而主日，配以月。夏后氏祭其闇，殷人祭其……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-20","chapterId":"li-ji_ch-24","order":20,"canonicalText":"天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓也。致反始，以厚其本也；致鬼神，以尊上也；致物用，以立民紀也。致義，則上下不悖逆矣。致讓，以去爭也。合此五者，以治天下之禮也，雖有奇邪，而不治者則微矣。","sentenceIds":["li-ji_ch-24_p-20_s-1","li-ji_ch-24_p-20_s-2","li-ji_ch-24_p-20_s-3","li-ji_ch-24_p-20_s-4","li-ji_ch-24_p-20_s-5","li-ji_ch-24_p-20_s-6","li-ji_ch-24_p-20_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天下的禮儀規程與道崇高德行與品性修養規範，致反始啊，致鬼神啊，致和用啊，致正義公道之道義啊，致讓啊。致反始，以厚他的本啊；致鬼神，以尊上啊；致物用，以立民紀啊。致正義公道之道義，則上下不悖逆矣。致讓，以去爭啊。合此五的人或禮儀規程與道崇高德行與品性修養規範制規範，以治天下的禮儀規程與道崇高德行與品性修養規範啊，雖有奇邪，而且不治的人或禮儀規程與道崇高德行與品性修養規範制規範則微矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 20 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-21","chapterId":"li-ji_ch-24","order":21,"canonicalText":"宰我曰：「吾聞鬼神之名，而不知其所謂。」子曰：「氣也者，神之盛也；魄也者，鬼之盛也；合鬼與神，教之至也。眾生必死，死必歸土：此之謂鬼。骨肉斃於下，陰為野土；其氣發揚於上，為昭明，焄蒿，悽愴，此百物之精也，神之著也。因物之精，制為之極，明命鬼神，以為黔首則。百眾以畏，萬民以服。」","sentenceIds":["li-ji_ch-24_p-21_s-1","li-ji_ch-24_p-21_s-2","li-ji_ch-24_p-21_s-3","li-ji_ch-24_p-21_s-4","li-ji_ch-24_p-21_s-5","li-ji_ch-24_p-21_s-6","li-ji_ch-24_p-21_s-7","li-ji_ch-24_p-21_s-8","li-ji_ch-24_p-21_s-9","li-ji_ch-24_p-21_s-10"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"宰我說道：「吾聞鬼神的名，而且不知他的所謂。」孔子先生親自開示教導說道：「氣啊的人或禮儀規程與道崇高德行與品性修養規範制規範，神的盛啊；魄啊的人或禮儀規程與道崇高德行與品性修養規範制規範，鬼的盛啊；合鬼與神，教的至啊。眾生必死，死必歸土：此的謂鬼。骨肉斃於下，陰為野土；他的氣發揚於上，為昭明，焄蒿，悽愴，此百物的精啊，神的著啊。因物的精，制為的極，明命鬼神，以為黔首則。百眾以畏，萬民以服。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 21 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「宰我曰：「吾聞鬼神之名，而不知其所謂」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「宰我曰：「吾聞鬼神之名，而不知其所謂。」子曰：「氣也……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-22","chapterId":"li-ji_ch-24","order":22,"canonicalText":"聖人以是為未足也，築為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘其所由生也。眾之服自此，故聽且速也。二端既立，報以二禮。建設朝事，燔燎羶薌，見以蕭光，以報氣也。此教眾反始也。薦黍稷，羞肝肺首心，見間以俠甒，加以鬱鬯，以報魄也。教民相愛，上下用情，禮之至也。","sentenceIds":["li-ji_ch-24_p-22_s-1","li-ji_ch-24_p-22_s-2","li-ji_ch-24_p-22_s-3","li-ji_ch-24_p-22_s-4","li-ji_ch-24_p-22_s-5","li-ji_ch-24_p-22_s-6","li-ji_ch-24_p-22_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"聖人以是為未足啊，築為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘他的所由生啊。眾的服自此，所以聽且速啊。二端既立，報以二禮儀規程與道崇高德行與品性修養規範。建設朝事，燔燎羶薌，見以蕭光，以報氣啊。此教眾反始啊。薦黍稷，羞肝肺首心，見間以俠甒，加以鬱鬯，以報魄啊。教民相愛，上下用情，禮儀規程與道崇高德行與品性修養規範的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 22 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「聖人以是為未足也，築為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘其所由生也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「聖人以是為未足也，築為宮室，謂為宗祧，以別親疏遠邇，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-23","chapterId":"li-ji_ch-24","order":23,"canonicalText":"君子反古復始，不忘其所由生也，是以致其敬，發其情，竭力從事，以報其親，不敢弗盡也。是故昔者天子為藉千畝，冕而朱紘，躬秉耒。諸侯為藉百畝，冕而青紘，躬秉耒，以事天地、山川、社稷、先古，以為醴酪齊盛，於是乎取之，敬之至也。","sentenceIds":["li-ji_ch-24_p-23_s-1","li-ji_ch-24_p-23_s-2","li-ji_ch-24_p-23_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"具有道德修養之君子賢士人階層反古復始，不忘他的所由生啊，是以致他的敬，發他的情，竭力從事，以報他的親，不敢弗盡啊。正因為如此昔的人或禮儀規程與道崇高德行與品性修養規範制規範天子為藉千畝，冕而且朱紘，躬秉耒。諸侯為藉百畝，冕而且青紘，躬秉耒，以事天地、山川、社稷、先古，以為醴酪齊盛，於是乎取的，敬的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 23 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君子反古復始，不忘其所由生也，是以致其敬，發其情，竭力從事，以報其親，不敢弗盡也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君子反古復始，不忘其所由生也，是以致其敬，發其情，竭……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-24","chapterId":"li-ji_ch-24","order":24,"canonicalText":"古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之。犧牷祭牲，必於是取之，敬之至也。君召牛，納而視之，擇其毛而卜之，吉，然後養之。君皮弁素積，朔月，月半，君巡牲，所以致力，孝之至也。","sentenceIds":["li-ji_ch-24_p-24_s-1","li-ji_ch-24_p-24_s-2","li-ji_ch-24_p-24_s-3","li-ji_ch-24_p-24_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古的人或禮儀規程與道崇高德行與品性修養規範制規範天子、諸侯必有養獸的官，及歲時，齊戒沐浴而且躬朝的。犧牷祭牲，必於是取的，敬的至啊。君召牛，納而且視的，擇他的毛而且卜的，吉，然後養的。君皮弁素積，朔月，月半，君巡牲，所以致力，孝的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 24 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-25","chapterId":"li-ji_ch-24","order":25,"canonicalText":"古者天子、諸侯必有公桑、蠶室，近川而為之。築宮仞有三尺，棘墻而外閉之。及大昕之朝，君皮弁素積，卜三宮之夫人世婦之吉者，使入蠶於蠶室，奉種浴於川；桑於公桑，風戾以食之。歲既殫矣，世婦卒蠶，奉繭以示於君，遂獻繭於夫人。夫人曰：「此所以為君服與？」遂副褘而受之，因少牢以禮之。古之獻繭者，其率用此與！及良日，夫人繅，三盆手，遂佈於三宮夫人世婦之吉者使繅；遂朱綠之，玄黃之，以為黼黻文章。服既成，君服以祀先王先公，敬之至也。","sentenceIds":["li-ji_ch-24_p-25_s-1","li-ji_ch-24_p-25_s-2","li-ji_ch-24_p-25_s-3","li-ji_ch-24_p-25_s-4","li-ji_ch-24_p-25_s-5","li-ji_ch-24_p-25_s-6","li-ji_ch-24_p-25_s-7","li-ji_ch-24_p-25_s-8","li-ji_ch-24_p-25_s-9","li-ji_ch-24_p-25_s-10","li-ji_ch-24_p-25_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古的人或禮儀規程與道崇高德行與品性修養規範制規範天子、諸侯必有公桑、蠶室，近川而且為的。築宮仞有三尺，棘墻而且外閉的。及大昕的朝，君皮弁素積，卜三宮的夫人世婦的吉的人或禮儀規程與道崇高德行與品性修養規範制規範，使入蠶於蠶室，奉種浴於川；桑於公桑，風戾以食的。歲既殫矣，世婦卒蠶，奉繭以示於君，遂獻繭於夫人。夫人說道：「此所以為君服與？」遂副褘而且受的，因少牢以禮儀規程與道崇高德行與品性修養規範的。古的獻繭的人或禮儀規程與道崇高德行與品性修養規範制規範，他的率用此與！及良日，夫人繅，三盆手，遂佈於三宮夫人世婦的吉的人或禮儀規程與道崇高德行與品性修養規範制規範使繅；遂朱綠的，玄黃的，以為黼黻文章。服既成，君服以祀先王先公，敬的至啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 25 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「古者天子、諸侯必有公桑、蠶室，近川而為之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「古者天子、諸侯必有公桑、蠶室，近川而為之。築宮仞有三……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-26","chapterId":"li-ji_ch-24","order":26,"canonicalText":"君子曰：禮樂不可斯須去身。致樂以治心，則易直子諒之心，油然生矣。易直子諒之心生則樂，樂則安，安則久，久則天，天則神。天則不言而信，神則不怒而威。致樂以治心者也。致禮以治躬則莊敬，莊敬則嚴威。心中斯須不和不樂，而鄙詐之心入之矣；外貌斯須不莊不敬，而慢易之心入之矣。","sentenceIds":["li-ji_ch-24_p-26_s-1","li-ji_ch-24_p-26_s-2","li-ji_ch-24_p-26_s-3","li-ji_ch-24_p-26_s-4","li-ji_ch-24_p-26_s-5","li-ji_ch-24_p-26_s-6","li-ji_ch-24_p-26_s-7","li-ji_ch-24_p-26_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君孔子先生親自開示教導說道：禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化不可斯須去身。致雅樂和聲與心靈感化以治心，則易直子諒的心，油然生矣。易直子諒的心生則雅樂和聲與心靈感化，雅樂和聲與心靈感化則安，安則久，久則天，天則神。天則不言而且信，神則不怒而且威。致雅樂和聲與心靈感化以治心的人或禮儀規程與道崇高德行與品性修養規範制規範啊。致禮儀規程與道崇高德行與品性修養規範以治躬則莊敬，莊敬則嚴威。心中斯須不和不雅樂和聲與心靈感化，而且鄙詐的心入的矣；外貌斯須不莊不敬，而且慢易的心入的矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 26 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君子曰：禮樂不可斯須去身」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君子曰：禮樂不可斯須去身。致樂以治心，則易直子諒之心……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-27","chapterId":"li-ji_ch-24","order":27,"canonicalText":"故樂也者，動於內者也，禮也者，動於外者也。樂極和，禮極順。內和而外順，則民瞻其顏色而不與爭也；望其容貌，而眾不生慢易焉。故德輝動乎內，而民莫不承聽；理發乎外，而眾莫不承順。故曰：致禮樂之道，而天下塞焉，舉而措之無難矣。","sentenceIds":["li-ji_ch-24_p-27_s-1","li-ji_ch-24_p-27_s-2","li-ji_ch-24_p-27_s-3","li-ji_ch-24_p-27_s-4","li-ji_ch-24_p-27_s-5","li-ji_ch-24_p-27_s-6","li-ji_ch-24_p-27_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以雅樂和聲與心靈感化啊的人或禮儀規程與道崇高德行與品性修養規範制規範，動於內的人或禮儀規程與道崇高德行與品性修養規範制規範啊，禮儀規程與道崇高德行與品性修養規範啊的人或禮儀規程與道崇高德行與品性修養規範制規範，動於外的人或禮儀規程與道崇高德行與品性修養規範制規範啊。雅樂和聲與心靈感化極和，禮儀規程與道崇高德行與品性修養規範極順。內和而且外順，則民瞻他的顏色而且不與爭啊；望他的容貌，而且眾不生慢易焉。所以崇高德行與品性修養輝動乎內，而且民莫不承聽；理發乎外，而且眾莫不承順。所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：致禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化的道，而且天下塞焉，舉而且措的無難矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 27 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「故樂也者，動於內者也，禮也者，動於外者也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「故樂也者，動於內者也，禮也者，動於外者也。樂極和，禮……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-28","chapterId":"li-ji_ch-24","order":28,"canonicalText":"樂也者，動於內者也；禮也者，動於外者也。故禮主其減，樂主其盈。禮減而進，以進為文；樂盈而反，以反為文。禮減而不進則銷，樂盈而不反則放。故禮有報而樂有反。禮得其報則樂，樂得其反則安。禮之報，樂之反，其義一也。","sentenceIds":["li-ji_ch-24_p-28_s-1","li-ji_ch-24_p-28_s-2","li-ji_ch-24_p-28_s-3","li-ji_ch-24_p-28_s-4","li-ji_ch-24_p-28_s-5","li-ji_ch-24_p-28_s-6","li-ji_ch-24_p-28_s-7","li-ji_ch-24_p-28_s-8","li-ji_ch-24_p-28_s-9"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"雅樂和聲與心靈感化啊的人或禮儀規程與道崇高德行與品性修養規範制規範，動於內的人或禮儀規程與道崇高德行與品性修養規範制規範啊；禮儀規程與道崇高德行與品性修養規範啊的人或禮儀規程與道崇高德行與品性修養規範制規範，動於外的人或禮儀規程與道崇高德行與品性修養規範制規範啊。所以禮儀規程與道崇高德行與品性修養規範主他的減，雅樂和聲與心靈感化主他的盈。禮儀規程與道崇高德行與品性修養規範減而且進，以進為文；雅樂和聲與心靈感化盈而且反，以反為文。禮儀規程與道崇高德行與品性修養規範減而且不進則銷，雅樂和聲與心靈感化盈而且不反則放。所以禮儀規程與道崇高德行與品性修養規範有報而且雅樂和聲與心靈感化有反。禮儀規程與道崇高德行與品性修養規範得他的報則雅樂和聲與心靈感化，雅樂和聲與心靈感化得他的反則安。禮儀規程與道崇高德行與品性修養規範的報，雅樂和聲與心靈感化的反，他的正義公道之道義一啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 28 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「樂也者，動於內者也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「樂也者，動於內者也；禮也者，動於外者也。故禮主其減，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-29","chapterId":"li-ji_ch-24","order":29,"canonicalText":"曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養。」公明儀問於曾子曰：「夫子可以為孝乎？」曾子曰：「是何言與！是何言與！君子之所為孝者：先意承志，諭父母於道。參，直養者也，安能為孝乎？」","sentenceIds":["li-ji_ch-24_p-29_s-1","li-ji_ch-24_p-29_s-2","li-ji_ch-24_p-29_s-3","li-ji_ch-24_p-29_s-4","li-ji_ch-24_p-29_s-5","li-ji_ch-24_p-29_s-6","li-ji_ch-24_p-29_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"曾孔子先生親自開示教導說道：「孝有三：大孝尊親，他的次弗辱，他的下能養。」公明儀問於曾孔子先生親自開示教導說道：「夫子可以為孝乎？」曾孔子先生親自開示教導說道：「是何言與！是何言與！具有道德修養之君子賢士人階層的所為孝的人或禮儀規程與道崇高德行與品性修養規範制規範：先意承志，諭父母於道。參，直養的人或禮儀規程與道崇高德行與品性修養規範制規範啊，安能為孝乎？」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 29 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養。」公……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-30","chapterId":"li-ji_ch-24","order":30,"canonicalText":"曾子曰：「身也者，父母之遺體也。行父母之遺體，敢不敬乎？居處不莊，非孝也；事君不忠，非孝也；蒞官不敬，非孝也；朋友不信，非孝也；戰陳無勇，非孝也；五者不遂，災及於親，敢不敬乎？","sentenceIds":["li-ji_ch-24_p-30_s-1","li-ji_ch-24_p-30_s-2","li-ji_ch-24_p-30_s-3","li-ji_ch-24_p-30_s-4","li-ji_ch-24_p-30_s-5","li-ji_ch-24_p-30_s-6","li-ji_ch-24_p-30_s-7","li-ji_ch-24_p-30_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"曾孔子先生親自開示教導說道：「身啊的人或禮儀規程與道崇高德行與品性修養規範制規範，父母的遺體啊。行父母的遺體，敢不敬乎？居處不莊，絕不是孝啊；事君不忠，絕不是孝啊；蒞官不敬，絕不是孝啊；朋友不信，絕不是孝啊；戰陳無勇，絕不是孝啊；五的人或禮儀規程與道崇高德行與品性修養規範制規範不遂，災及於親，敢不敬乎？","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 30 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「曾子曰：「身也者，父母之遺體也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「曾子曰：「身也者，父母之遺體也。行父母之遺體，敢不敬……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-31","chapterId":"li-ji_ch-24","order":31,"canonicalText":"亨孰羶薌，嘗而薦之，非孝也，養也。君子之所謂孝也者，國人稱願然曰：『幸哉有子！』如此，所謂孝也已。眾之本教曰孝，其行曰養。養，可能也，敬為難；敬，可能也，安為難；安，可能也，卒為難。父母既沒，慎行其身，不遺父母惡名，可謂能終矣。仁者，仁此者也；禮者，履此者也；義者，宜此者也；信者，信此者也；強者，強此者也。樂自順此生，刑自反此作。」","sentenceIds":["li-ji_ch-24_p-31_s-1","li-ji_ch-24_p-31_s-2","li-ji_ch-24_p-31_s-3","li-ji_ch-24_p-31_s-4","li-ji_ch-24_p-31_s-5","li-ji_ch-24_p-31_s-6","li-ji_ch-24_p-31_s-7","li-ji_ch-24_p-31_s-8","li-ji_ch-24_p-31_s-9","li-ji_ch-24_p-31_s-10","li-ji_ch-24_p-31_s-11","li-ji_ch-24_p-31_s-12","li-ji_ch-24_p-31_s-13","li-ji_ch-24_p-31_s-14","li-ji_ch-24_p-31_s-15"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"亨孰羶薌，嘗而且薦的，絕不是孝啊，養啊。具有道德修養之君子賢士人階層的所謂孝啊的人或禮儀規程與道崇高德行與品性修養規範制規範，國人稱願然說道：『幸哉有子！』如此，所謂孝啊已。眾的本教說道：孝，他的行說道：養。養，可能啊，敬為難；敬，可能啊，安為難；安，可能啊，卒為難。父母既沒，慎行他的身，不遺父母惡名，可謂能終矣。仁愛慈惠之聖德的人或禮儀規程與道崇高德行與品性修養規範制規範，仁愛慈惠之聖德此的人或禮儀規程與道崇高德行與品性修養規範制規範啊；禮儀規程與道崇高德行與品性修養規範的人或禮儀規程與道崇高德行與品性修養規範制規範，履此的人或禮儀規程與道崇高德行與品性修養規範制規範啊；正義公道之道義的人或禮儀規程與道崇高德行與品性修養規範制規範，宜此的人或禮儀規程與道崇高德行與品性修養規範制規範啊；信的人或禮儀規程與道崇高德行與品性修養規範制規範，信此的人或禮儀規程與道崇高德行與品性修養規範制規範啊；強的人或禮儀規程與道崇高德行與品性修養規範制規範，強此的人或禮儀規程與道崇高德行與品性修養規範制規範啊。雅樂和聲與心靈感化自順此生，刑自反此作。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 31 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「亨孰羶薌，嘗而薦之，非孝也，養也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「亨孰羶薌，嘗而薦之，非孝也，養也。君子之所謂孝也者，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-32","chapterId":"li-ji_ch-24","order":32,"canonicalText":"曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸後世而無朝夕，推而放諸東海而準，推而放諸西海而準，推而放諸南海而準，推而放諸北海而準。《詩》雲：『自西自東，自南自北，無思不服。』此之謂也。」","sentenceIds":["li-ji_ch-24_p-32_s-1","li-ji_ch-24_p-32_s-2","li-ji_ch-24_p-32_s-3","li-ji_ch-24_p-32_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"曾孔子先生親自開示教導說道：「夫孝，置的而且塞乎天地，溥的而且橫乎四海，施諸後世而且無朝夕，推而且放諸東海而且準，推而且放諸西海而且準，推而且放諸南海而且準，推而且放諸北海而且準。《詩》雲：『自西自東，自南自北，無思不服。』此的謂啊。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 32 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸後世而無朝夕，推而放諸東海而準，推而放諸西海而準，推而放諸南海而準，推而放諸北海而準」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-33","chapterId":"li-ji_ch-24","order":33,"canonicalText":"曾子曰：「樹木以時伐焉，禽獸以時殺焉。夫子曰：『斷一樹，殺一獸，不以其時，非孝也。』孝有三：小孝用力，中孝用勞，大孝不匱。思慈愛忘勞，可謂用力矣。尊仁安義，可謂用勞矣。博施備物，可謂不匱矣。父母愛之，嘉而弗忘；父母惡之，懼而無怨；父母有過，諫而不逆；父母既沒，必求仁者之粟以祀之。此之謂禮終。」","sentenceIds":["li-ji_ch-24_p-33_s-1","li-ji_ch-24_p-33_s-2","li-ji_ch-24_p-33_s-3","li-ji_ch-24_p-33_s-4","li-ji_ch-24_p-33_s-5","li-ji_ch-24_p-33_s-6","li-ji_ch-24_p-33_s-7","li-ji_ch-24_p-33_s-8","li-ji_ch-24_p-33_s-9","li-ji_ch-24_p-33_s-10","li-ji_ch-24_p-33_s-11","li-ji_ch-24_p-33_s-12"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"曾孔子先生親自開示教導說道：「樹木以時伐焉，禽獸以時殺焉。夫孔子先生親自開示教導說道：『斷一樹，殺一獸，不以他的時，絕不是孝啊。』孝有三：小孝用力，中孝用勞，大孝不匱。思慈愛忘勞，可謂用力矣。尊仁愛慈惠之聖德安正義公道之道義，可謂用勞矣。博施備物，可謂不匱矣。父母愛的，嘉而且弗忘；父母惡的，懼而且無怨；父母有過，諫而且不逆；父母既沒，必求仁愛慈惠之聖德的人或禮儀規程與道崇高德行與品性修養規範制規範的粟以祀的。此的謂禮儀規程與道崇高德行與品性修養規範終。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 33 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「曾子曰：「樹木以時伐焉，禽獸以時殺焉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「曾子曰：「樹木以時伐焉，禽獸以時殺焉。夫子曰：『斷一……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-34","chapterId":"li-ji_ch-24","order":34,"canonicalText":"樂正子春下堂而傷其足，數月不出，猶有憂色。門弟子曰：「夫子之足瘳矣，數月不出，猶有憂色，何也？」樂正子春曰：「善如爾之問也！善如爾之問也！吾聞諸曾子，曾子聞諸夫子曰：『天之所生，地之所養，無人為大。』父母全而生之，子全而歸之，可謂孝矣。不虧其體，不辱其身，可謂全矣。故君子頃步而弗敢忘孝也。今予忘孝之道，予是以有憂色也。壹舉足而不敢忘父母，壹出言而不敢忘父母。壹舉足而不敢忘父母，是故道而不徑，舟而不遊，不敢以先父母之遺體行殆。壹出言而不敢忘父母，是故惡言不出於口，忿言不反於身。不辱其身，不羞其親，可謂孝矣。」","sentenceIds":["li-ji_ch-24_p-34_s-1","li-ji_ch-24_p-34_s-2","li-ji_ch-24_p-34_s-3","li-ji_ch-24_p-34_s-4","li-ji_ch-24_p-34_s-5","li-ji_ch-24_p-34_s-6","li-ji_ch-24_p-34_s-7","li-ji_ch-24_p-34_s-8","li-ji_ch-24_p-34_s-9","li-ji_ch-24_p-34_s-10","li-ji_ch-24_p-34_s-11","li-ji_ch-24_p-34_s-12","li-ji_ch-24_p-34_s-13","li-ji_ch-24_p-34_s-14"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"雅樂和聲與心靈感化正子春下堂而且傷他的足，數月不出，猶有憂色。門弟孔子先生親自開示教導說道：「夫子的足瘳矣，數月不出，猶有憂色，何啊？」雅樂和聲與心靈感化正子春說道：「善如爾的問啊！善如爾的問啊！吾聞諸曾子，曾子聞諸夫孔子先生親自開示教導說道：『天的所生，地的所養，無人為大。』父母全而且生的，子全而且歸的，可謂孝矣。不虧他的體，不辱他的身，可謂全矣。所以具有道德修養之君子賢士人階層頃步而且弗敢忘孝啊。今予忘孝的道，予是以有憂色啊。壹舉足而且不敢忘父母，壹出言而且不敢忘父母。壹舉足而且不敢忘父母，正因為如此道而且不徑，舟而且不遊，不敢以先父母的遺體行殆。壹出言而且不敢忘父母，正因為如此惡言不出於口，忿言不反於身。不辱他的身，不羞他的親，可謂孝矣。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 34 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「樂正子春下堂而傷其足，數月不出，猶有憂色」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「樂正子春下堂而傷其足，數月不出，猶有憂色。門弟子曰：……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-35","chapterId":"li-ji_ch-24","order":35,"canonicalText":"昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而尚齒，周人貴親而尚齒。虞夏殷周，天下之盛王也，未有遺年者。年之貴乎天下，久矣；次乎事親也。","sentenceIds":["li-ji_ch-24_p-35_s-1","li-ji_ch-24_p-35_s-2","li-ji_ch-24_p-35_s-3","li-ji_ch-24_p-35_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昔的人或禮儀規程與道崇高德行與品性修養規範制規範，有虞氏貴崇高德行與品性修養而且尚齒，夏后氏貴爵而且尚齒，殷人貴富而且尚齒，周人貴親而且尚齒。虞夏殷周，天下的盛王啊，未有遺年的人或禮儀規程與道崇高德行與品性修養規範制規範。年的貴乎天下，久矣；次乎事親啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 35 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而尚齒，周人貴親而尚齒」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-36","chapterId":"li-ji_ch-24","order":36,"canonicalText":"是故朝廷同爵則尚齒。七十杖於朝，君問則席。八十不俟朝，君問則就之，而弟達乎朝廷矣。","sentenceIds":["li-ji_ch-24_p-36_s-1","li-ji_ch-24_p-36_s-2","li-ji_ch-24_p-36_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"正因為如此朝廷同爵則尚齒。七十杖於朝，君問則席。八十不俟朝，君問則就的，而且弟達乎朝廷矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 36 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是故朝廷同爵則尚齒」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是故朝廷同爵則尚齒。七十杖於朝，君問則席。八十不俟朝……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-37","chapterId":"li-ji_ch-24","order":37,"canonicalText":"行，肩而不併，不錯則隨。見老者，則車徒闢；斑白者不以其任行乎道路，而弟達乎道路矣。居鄉以齒，而老窮不遺，強不犯弱，眾不暴寡，而弟達乎州巷矣。","sentenceIds":["li-ji_ch-24_p-37_s-1","li-ji_ch-24_p-37_s-2","li-ji_ch-24_p-37_s-3","li-ji_ch-24_p-37_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"行，肩而且不併，不錯則隨。見老的人或禮儀規程與道崇高德行與品性修養規範制規範，則車徒闢；斑白的人或禮儀規程與道崇高德行與品性修養規範制規範不以他的任行乎道路，而且弟達乎道路矣。居鄉以齒，而且老窮不遺，強不犯弱，眾不暴寡，而且弟達乎州巷矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 37 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「行，肩而不併，不錯則隨」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「行，肩而不併，不錯則隨。見老者，則車徒闢；斑白者不以……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-38","chapterId":"li-ji_ch-24","order":38,"canonicalText":"古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣。軍旅什伍，同爵則尚齒，而弟達乎軍旅矣。","sentenceIds":["li-ji_ch-24_p-38_s-1","li-ji_ch-24_p-38_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古的道，五十不為甸徒，頒禽隆諸長的人或禮儀規程與道崇高德行與品性修養規範制規範，而且弟達乎蒐狩矣。軍旅什伍，同爵則尚齒，而且弟達乎軍旅矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 38 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-39","chapterId":"li-ji_ch-24","order":39,"canonicalText":"孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以義死之，而弗敢犯也。","sentenceIds":["li-ji_ch-24_p-39_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以正義公道之道義死的，而且弗敢犯啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 39 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以義死之，而弗敢犯也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-40","chapterId":"li-ji_ch-24","order":40,"canonicalText":"祀乎明堂，所以教諸侯之孝也；食三老五更於大學，所以教諸侯之弟也。祀先賢於西學，所以教諸侯之德也；耕藉，所以教諸侯之養也；朝覲，所以教諸侯之臣也。五者，天下之大教也。","sentenceIds":["li-ji_ch-24_p-40_s-1","li-ji_ch-24_p-40_s-2","li-ji_ch-24_p-40_s-3","li-ji_ch-24_p-40_s-4","li-ji_ch-24_p-40_s-5","li-ji_ch-24_p-40_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"祀乎明堂，所以教諸侯的孝啊；食三老五更於大學，所以教諸侯的弟啊。祀先賢於西學，所以教諸侯的崇高德行與品性修養啊；耕藉，所以教諸侯的養啊；朝覲，所以教諸侯的臣啊。五的人或禮儀規程與道崇高德行與品性修養規範制規範，天下的大教啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 40 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「祀乎明堂，所以教諸侯之孝也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「祀乎明堂，所以教諸侯之孝也；食三老五更於大學，所以教……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-41","chapterId":"li-ji_ch-24","order":41,"canonicalText":"食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總幹，所以教諸侯之弟也。是故，鄉里有齒，而老窮不遺，強不犯弱，眾不暴寡，此由大學來者也。天子設四學，當入學，而大子齒。","sentenceIds":["li-ji_ch-24_p-41_s-1","li-ji_ch-24_p-41_s-2","li-ji_ch-24_p-41_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"食三老五更於大學，天子袒而且割牲，執醬而且饋，執爵而且酳，冕而且總幹，所以教諸侯的弟啊。正因為如此，鄉里有齒，而且老窮不遺，強不犯弱，眾不暴寡，此由大學來的人或禮儀規程與道崇高德行與品性修養規範制規範啊。天子設四學，當入學，而且大子齒。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 41 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總幹，所以教諸侯之弟也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-42","chapterId":"li-ji_ch-24","order":42,"canonicalText":"天子巡守，諸侯待於竟。天子先見百年者。八、十九十者東行，西行者弗敢過；西行，東行者弗敢過。欲言政者，君就之可也。","sentenceIds":["li-ji_ch-24_p-42_s-1","li-ji_ch-24_p-42_s-2","li-ji_ch-24_p-42_s-3","li-ji_ch-24_p-42_s-4","li-ji_ch-24_p-42_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天子巡守，諸侯待於竟。天子先見百年的人或禮儀規程與道崇高德行與品性修養規範制規範。八、十九十的人或禮儀規程與道崇高德行與品性修養規範制規範東行，西行的人或禮儀規程與道崇高德行與品性修養規範制規範弗敢過；西行，東行的人或禮儀規程與道崇高德行與品性修養規範制規範弗敢過。欲言政的人或禮儀規程與道崇高德行與品性修養規範制規範，君就的可啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 42 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子巡守，諸侯待於竟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子巡守，諸侯待於竟。天子先見百年者。八、十九十者東……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-43","chapterId":"li-ji_ch-24","order":43,"canonicalText":"壹命齒於鄉里，再命齒於族，三命不齒；族有七十者，弗敢先。七十者，不有大故不入朝；若有大故而入，君必與之揖讓，而後及爵者。","sentenceIds":["li-ji_ch-24_p-43_s-1","li-ji_ch-24_p-43_s-2","li-ji_ch-24_p-43_s-3","li-ji_ch-24_p-43_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"壹命齒於鄉里，再命齒於族，三命不齒；族有七十的人或禮儀規程與道崇高德行與品性修養規範制規範，弗敢先。七十的人或禮儀規程與道崇高德行與品性修養規範制規範，不有大所以不入朝；若有大所以而且入，君必與的揖讓，而且後及爵的人或禮儀規程與道崇高德行與品性修養規範制規範。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 43 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「壹命齒於鄉里，再命齒於族，三命不齒」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「壹命齒於鄉里，再命齒於族，三命不齒；族有七十者，弗敢……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-44","chapterId":"li-ji_ch-24","order":44,"canonicalText":"天子有善，讓德於天；諸侯有善，歸諸天子；卿大夫有善，薦於諸侯；士、庶人有善，本諸父母，存諸長老；祿爵慶賞，成諸宗廟；所以示順也。","sentenceIds":["li-ji_ch-24_p-44_s-1","li-ji_ch-24_p-44_s-2","li-ji_ch-24_p-44_s-3","li-ji_ch-24_p-44_s-4","li-ji_ch-24_p-44_s-5","li-ji_ch-24_p-44_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天子有善，讓崇高德行與品性修養於天；諸侯有善，歸諸天子；卿卿大夫貴族官員有善，薦於諸侯；士人階層、平民百姓有善，本諸父母，存諸長老；祿爵慶賞，成諸宗廟；所以示順啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 44 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子有善，讓德於天」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子有善，讓德於天；諸侯有善，歸諸天子；卿大夫有善，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-45","chapterId":"li-ji_ch-24","order":45,"canonicalText":"昔者，聖人建陰陽天地之情，立以為《易》。易抱龜南面，天子卷冕北面，雖有明知之心，必進斷其志焉。示不敢專，以尊天也。善則稱人，過則稱己。教不伐以尊賢也。","sentenceIds":["li-ji_ch-24_p-45_s-1","li-ji_ch-24_p-45_s-2","li-ji_ch-24_p-45_s-3","li-ji_ch-24_p-45_s-4","li-ji_ch-24_p-45_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昔的人或禮儀規程與道崇高德行與品性修養規範制規範，聖人建陰陽天地的情，立以為《易》。易抱龜南面，天子卷冕北面，雖有明知的心，必進斷他的志焉。示不敢專，以尊天啊。善則稱人，過則稱己。教不伐以尊賢啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 45 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「昔者，聖人建陰陽天地之情，立以為《易》」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「昔者，聖人建陰陽天地之情，立以為《易》。易抱龜南面，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-46","chapterId":"li-ji_ch-24","order":46,"canonicalText":"孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，以治百事。及祭之日，顏色必溫，行必恐，如懼不及愛然。其奠之也，容貌必溫，身必詘，如語焉而未之然。宿者皆出，其立卑靜以正，如將弗見然。及祭之後，陶陶遂遂，如將復入然。是故，愨善不違身，耳目不違心，思慮不違親。結諸心，形諸色，而術省之，孝子之志也。","sentenceIds":["li-ji_ch-24_p-46_s-1","li-ji_ch-24_p-46_s-2","li-ji_ch-24_p-46_s-3","li-ji_ch-24_p-46_s-4","li-ji_ch-24_p-46_s-5","li-ji_ch-24_p-46_s-6","li-ji_ch-24_p-46_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孝子將祭祀，必有齊莊的心以慮事，以具服物，以修宮室，以治百事。及祭的日，顏色必溫，行必恐，如懼不及愛然。他的奠的啊，容貌必溫，身必詘，如語焉而且未的然。宿的人或禮儀規程與道崇高德行與品性修養規範制規範皆出，他的立卑靜以正，如將弗見然。及祭的後，陶陶遂遂，如將復入然。正因為如此，愨善不違身，耳目不違心，思慮不違親。結諸心，形諸色，而且術省的，孝子的志啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 46 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，以治百事」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-24_p-47","chapterId":"li-ji_ch-24","order":47,"canonicalText":"建國之神位：右社稷，而左宗廟。","sentenceIds":["li-ji_ch-24_p-47_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"建國的神位：右社稷，而且左宗廟。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭義〉（第 47 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「建國之神位：右社稷，而左宗廟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「建國之神位：右社稷，而左宗廟。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"li-ji_ch-24_p-1_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":1,"canonicalText":"祭不欲數，數則煩，煩則不敬。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-1_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":2,"canonicalText":"祭不欲疏，疏則怠，怠則忘。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-1_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":3,"canonicalText":"是故君子合諸天道：春禘秋嘗。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-1_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":4,"canonicalText":"霜露既降，君子履之，必有悽愴之心，非其寒之謂也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-1_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":5,"canonicalText":"春，雨露既濡，君子履之，必有怵惕之心，如將見之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-1_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-1","order":6,"canonicalText":"樂以迎來，哀以送往，故禘有樂而嘗無樂。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-2_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-2","order":1,"canonicalText":"致齊於內，散齊於外。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-2_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-2","order":2,"canonicalText":"齊之日：思其居處，思其笑語，思其志意，思其所樂，思其所嗜。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-2_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-2","order":3,"canonicalText":"齊三日，乃見其所為齊者。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-3_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-3","order":1,"canonicalText":"祭之日：入室，僾然必有見乎其位，周還出戶，肅然必有聞乎其容聲，出戶而聽，愾然必有聞乎其嘆息之聲。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-4_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-4","order":1,"canonicalText":"是故，先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜慾不忘乎心。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-4_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-4","order":2,"canonicalText":"致愛則存，致愨則著。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-4_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-4","order":3,"canonicalText":"著存不忘乎心，夫安得不敬乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-5_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-5","order":1,"canonicalText":"君子生則敬養，死則敬享，思終身弗辱也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-5_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-5","order":2,"canonicalText":"君子有終身之喪，忌日之謂也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-5_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-5","order":3,"canonicalText":"忌日不用，非不祥也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-5_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-5","order":4,"canonicalText":"言夫日，志有所至，而不敢盡其私也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":1,"canonicalText":"唯聖人為能饗帝，孝子為能饗親。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":2,"canonicalText":"饗者，鄉也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":3,"canonicalText":"鄉之，然後能饗焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":4,"canonicalText":"是故孝子臨屍而不怍。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":5,"canonicalText":"君牽牲，夫人奠盎。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":6,"canonicalText":"君獻屍，夫人薦豆。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":7,"canonicalText":"卿大夫相君，命婦相夫人。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-6_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-6","order":8,"canonicalText":"齊齊乎其敬也，愉愉乎其忠也，勿勿諸其欲其饗之也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":1,"canonicalText":"文王之祭也：事死者如事生，思死者如不欲生，忌日必哀，稱諱如見親。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":2,"canonicalText":"祀之忠也，如見親之所愛，如欲色然；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":3,"canonicalText":"其文王與？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":4,"canonicalText":"《詩》雲：「明發不寐，有懷二人。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":5,"canonicalText":"」文王之詩也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":6,"canonicalText":"祭之明日，明發不寐，饗而致之，又從而思之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":7,"canonicalText":"祭之日，樂與哀半；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-7_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-7","order":8,"canonicalText":"饗之必樂，已至必哀。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-8_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-8","order":1,"canonicalText":"仲尼嘗，奉薦而進其親也愨，其行趨趨以數。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-8_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-8","order":2,"canonicalText":"已祭，子贛問曰：「子之言祭，濟濟漆漆然；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-8_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-8","order":3,"canonicalText":"今子之祭，無濟濟漆漆，何也？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-8_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-8","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":1,"canonicalText":"子曰：「濟濟者，容也遠也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":2,"canonicalText":"漆漆者，容也自反也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":3,"canonicalText":"容以遠，若容以自反也，夫何神明之及交，夫何濟濟漆漆之有乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":4,"canonicalText":"反饋，樂成，薦其薦俎，序其禮樂，備其百官。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":5,"canonicalText":"君子致其濟濟漆漆，夫何慌惚之有乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":6,"canonicalText":"夫言，豈一端而已？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":7,"canonicalText":"夫各有所當也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-9_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-9","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":1,"canonicalText":"孝子將祭，慮事不可以不豫；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":2,"canonicalText":"比時具物，不可以不備；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":3,"canonicalText":"虛中以治之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":4,"canonicalText":"宮室既修，墻屋既設，百物既備，夫婦齊戒沐浴，盛服奉承而進之，洞洞乎，屬屬乎，如弗勝，如將失之，其孝敬之心至也與！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":5,"canonicalText":"薦其薦俎，序其禮樂，備其百官，奉承而進之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":6,"canonicalText":"於是諭其志意，以其恍惚以與神明交，庶或饗之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-10_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-10","order":7,"canonicalText":"「庶或饗之」，孝子之志也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-11_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-11","order":1,"canonicalText":"孝子之祭也，盡其愨而愨焉，盡其信而信焉，盡其敬而敬焉，盡其禮而不過失焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-11_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-11","order":2,"canonicalText":"進退必敬，如親聽命，則或使之也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":1,"canonicalText":"孝子之祭，可知也，其立之也敬以詘，其進之也敬以愉，其薦之也敬以欲；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":2,"canonicalText":"退而立，如將受命；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":3,"canonicalText":"已徹而退，敬齊之色不絕於面。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":4,"canonicalText":"孝子之祭也，立而不詘，固也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":5,"canonicalText":"進而不愉，疏也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":6,"canonicalText":"薦而不欲，不愛也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":7,"canonicalText":"退立而不如受命，敖也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":8,"canonicalText":"已徹而退，無敬齊之色，而忘本也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-12_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-12","order":9,"canonicalText":"如是而祭，失之矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-13_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-13","order":1,"canonicalText":"孝子之有深愛者，必有和氣；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-13_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-13","order":2,"canonicalText":"有和氣者，必有愉色；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-13_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-13","order":3,"canonicalText":"有愉色者，必有婉容。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-13_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-13","order":4,"canonicalText":"孝子如執玉，如奉盈，洞洞屬屬然，如弗勝，如將失之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-13_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-13","order":5,"canonicalText":"嚴威儼恪，非所以事親也，成人之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":1,"canonicalText":"先王之所以治天下者五：貴有德，貴貴，貴老，敬長，慈幼。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":2,"canonicalText":"此五者，先王之所以定天下也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":3,"canonicalText":"貴有德，何為也？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":4,"canonicalText":"為其近於道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":5,"canonicalText":"貴貴，為其近於君也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":6,"canonicalText":"貴老，為其近於親也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":7,"canonicalText":"敬長，為其近於兄也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-14_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-14","order":8,"canonicalText":"慈幼，為其近於子也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-15_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-15","order":1,"canonicalText":"是故至孝近乎王，至弟近乎霸。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-15_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-15","order":2,"canonicalText":"至孝近乎王，雖天子，必有父；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-15_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-15","order":3,"canonicalText":"至弟近乎霸，雖諸侯，必有兄。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-15_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-15","order":4,"canonicalText":"先王之教，因而弗改，所以領天下國家也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":1,"canonicalText":"子曰：「立愛自親始，教民睦也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":2,"canonicalText":"立教自長始，教民順也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":3,"canonicalText":"教以慈睦，而民貴有親；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":4,"canonicalText":"教以敬長，而民貴用命。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":5,"canonicalText":"孝以事親，順以聽命，錯諸天下，無所不行。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-16_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-16","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-17_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-17","order":1,"canonicalText":"郊之祭也，喪者不敢哭，凶服者不敢入國門，敬之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-18_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-18","order":1,"canonicalText":"祭之日，君牽牲，穆答君，卿大夫序從。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-18_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-18","order":2,"canonicalText":"既入廟門，麗於碑，卿大夫袒，而毛牛尚耳，鸞刀以刲，取膟菺，乃退。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-18_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-18","order":3,"canonicalText":"爓祭，祭腥而退，敬之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":1,"canonicalText":"郊之祭，大報天而主日，配以月。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":2,"canonicalText":"夏后氏祭其闇，殷人祭其陽，周人祭日，以朝及闇。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":3,"canonicalText":"祭日於壇，祭月於坎，以別幽明，以制上下。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":4,"canonicalText":"祭日於東，祭月於西，以別外內，以端其位。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":5,"canonicalText":"日出於東，月生於西。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-19_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-19","order":6,"canonicalText":"陰陽長短，終始相巡，以致天下之和。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":1,"canonicalText":"天下之禮，致反始也，致鬼神也，致和用也，致義也，致讓也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":2,"canonicalText":"致反始，以厚其本也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":3,"canonicalText":"致鬼神，以尊上也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":4,"canonicalText":"致物用，以立民紀也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":5,"canonicalText":"致義，則上下不悖逆矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":6,"canonicalText":"致讓，以去爭也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-20_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-20","order":7,"canonicalText":"合此五者，以治天下之禮也，雖有奇邪，而不治者則微矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":1,"canonicalText":"宰我曰：「吾聞鬼神之名，而不知其所謂。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":2,"canonicalText":"」子曰：「氣也者，神之盛也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":3,"canonicalText":"魄也者，鬼之盛也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":4,"canonicalText":"合鬼與神，教之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":5,"canonicalText":"眾生必死，死必歸土：此之謂鬼。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":6,"canonicalText":"骨肉斃於下，陰為野土；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":7,"canonicalText":"其氣發揚於上，為昭明，焄蒿，悽愴，此百物之精也，神之著也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":8,"canonicalText":"因物之精，制為之極，明命鬼神，以為黔首則。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":9,"canonicalText":"百眾以畏，萬民以服。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-21_s-10","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-21","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":1,"canonicalText":"聖人以是為未足也，築為宮室，謂為宗祧，以別親疏遠邇，教民反古復始，不忘其所由生也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":2,"canonicalText":"眾之服自此，故聽且速也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":3,"canonicalText":"二端既立，報以二禮。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":4,"canonicalText":"建設朝事，燔燎羶薌，見以蕭光，以報氣也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":5,"canonicalText":"此教眾反始也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":6,"canonicalText":"薦黍稷，羞肝肺首心，見間以俠甒，加以鬱鬯，以報魄也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-22_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-22","order":7,"canonicalText":"教民相愛，上下用情，禮之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-23_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-23","order":1,"canonicalText":"君子反古復始，不忘其所由生也，是以致其敬，發其情，竭力從事，以報其親，不敢弗盡也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-23_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-23","order":2,"canonicalText":"是故昔者天子為藉千畝，冕而朱紘，躬秉耒。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-23_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-23","order":3,"canonicalText":"諸侯為藉百畝，冕而青紘，躬秉耒，以事天地、山川、社稷、先古，以為醴酪齊盛，於是乎取之，敬之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-24_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-24","order":1,"canonicalText":"古者天子、諸侯必有養獸之官，及歲時，齊戒沐浴而躬朝之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-24_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-24","order":2,"canonicalText":"犧牷祭牲，必於是取之，敬之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-24_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-24","order":3,"canonicalText":"君召牛，納而視之，擇其毛而卜之，吉，然後養之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-24_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-24","order":4,"canonicalText":"君皮弁素積，朔月，月半，君巡牲，所以致力，孝之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":1,"canonicalText":"古者天子、諸侯必有公桑、蠶室，近川而為之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":2,"canonicalText":"築宮仞有三尺，棘墻而外閉之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":3,"canonicalText":"及大昕之朝，君皮弁素積，卜三宮之夫人世婦之吉者，使入蠶於蠶室，奉種浴於川；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":4,"canonicalText":"桑於公桑，風戾以食之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":5,"canonicalText":"歲既殫矣，世婦卒蠶，奉繭以示於君，遂獻繭於夫人。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":6,"canonicalText":"夫人曰：「此所以為君服與？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":7,"canonicalText":"」遂副褘而受之，因少牢以禮之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":8,"canonicalText":"古之獻繭者，其率用此與！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":9,"canonicalText":"及良日，夫人繅，三盆手，遂佈於三宮夫人世婦之吉者使繅；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-10","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":10,"canonicalText":"遂朱綠之，玄黃之，以為黼黻文章。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-25_s-11","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-25","order":11,"canonicalText":"服既成，君服以祀先王先公，敬之至也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":1,"canonicalText":"君子曰：禮樂不可斯須去身。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":2,"canonicalText":"致樂以治心，則易直子諒之心，油然生矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":3,"canonicalText":"易直子諒之心生則樂，樂則安，安則久，久則天，天則神。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":4,"canonicalText":"天則不言而信，神則不怒而威。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":5,"canonicalText":"致樂以治心者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":6,"canonicalText":"致禮以治躬則莊敬，莊敬則嚴威。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":7,"canonicalText":"心中斯須不和不樂，而鄙詐之心入之矣；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-26_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-26","order":8,"canonicalText":"外貌斯須不莊不敬，而慢易之心入之矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":1,"canonicalText":"故樂也者，動於內者也，禮也者，動於外者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":2,"canonicalText":"樂極和，禮極順。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":3,"canonicalText":"內和而外順，則民瞻其顏色而不與爭也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":4,"canonicalText":"望其容貌，而眾不生慢易焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":5,"canonicalText":"故德輝動乎內，而民莫不承聽；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":6,"canonicalText":"理發乎外，而眾莫不承順。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-27_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-27","order":7,"canonicalText":"故曰：致禮樂之道，而天下塞焉，舉而措之無難矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":1,"canonicalText":"樂也者，動於內者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":2,"canonicalText":"禮也者，動於外者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":3,"canonicalText":"故禮主其減，樂主其盈。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":4,"canonicalText":"禮減而進，以進為文；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":5,"canonicalText":"樂盈而反，以反為文。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":6,"canonicalText":"禮減而不進則銷，樂盈而不反則放。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":7,"canonicalText":"故禮有報而樂有反。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":8,"canonicalText":"禮得其報則樂，樂得其反則安。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-28_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-28","order":9,"canonicalText":"禮之報，樂之反，其義一也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":1,"canonicalText":"曾子曰：「孝有三：大孝尊親，其次弗辱，其下能養。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":2,"canonicalText":"」公明儀問於曾子曰：「夫子可以為孝乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":3,"canonicalText":"」曾子曰：「是何言與！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":4,"canonicalText":"是何言與！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":5,"canonicalText":"君子之所為孝者：先意承志，諭父母於道。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":6,"canonicalText":"參，直養者也，安能為孝乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-29_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-29","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":1,"canonicalText":"曾子曰：「身也者，父母之遺體也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":2,"canonicalText":"行父母之遺體，敢不敬乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":3,"canonicalText":"居處不莊，非孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":4,"canonicalText":"事君不忠，非孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":5,"canonicalText":"蒞官不敬，非孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":6,"canonicalText":"朋友不信，非孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":7,"canonicalText":"戰陳無勇，非孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-30_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-30","order":8,"canonicalText":"五者不遂，災及於親，敢不敬乎？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":1,"canonicalText":"亨孰羶薌，嘗而薦之，非孝也，養也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":2,"canonicalText":"君子之所謂孝也者，國人稱願然曰：『幸哉有子！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":3,"canonicalText":"』如此，所謂孝也已。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":4,"canonicalText":"眾之本教曰孝，其行曰養。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":5,"canonicalText":"養，可能也，敬為難；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":6,"canonicalText":"敬，可能也，安為難；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":7,"canonicalText":"安，可能也，卒為難。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":8,"canonicalText":"父母既沒，慎行其身，不遺父母惡名，可謂能終矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":9,"canonicalText":"仁者，仁此者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-10","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":10,"canonicalText":"禮者，履此者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-11","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":11,"canonicalText":"義者，宜此者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-12","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":12,"canonicalText":"信者，信此者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-13","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":13,"canonicalText":"強者，強此者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-14","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":14,"canonicalText":"樂自順此生，刑自反此作。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-31_s-15","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-31","order":15,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-32_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-32","order":1,"canonicalText":"曾子曰：「夫孝，置之而塞乎天地，溥之而橫乎四海，施諸後世而無朝夕，推而放諸東海而準，推而放諸西海而準，推而放諸南海而準，推而放諸北海而準。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-32_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-32","order":2,"canonicalText":"《詩》雲：『自西自東，自南自北，無思不服。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-32_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-32","order":3,"canonicalText":"』此之謂也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-32_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-32","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":1,"canonicalText":"曾子曰：「樹木以時伐焉，禽獸以時殺焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":2,"canonicalText":"夫子曰：『斷一樹，殺一獸，不以其時，非孝也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":3,"canonicalText":"』孝有三：小孝用力，中孝用勞，大孝不匱。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":4,"canonicalText":"思慈愛忘勞，可謂用力矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":5,"canonicalText":"尊仁安義，可謂用勞矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":6,"canonicalText":"博施備物，可謂不匱矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":7,"canonicalText":"父母愛之，嘉而弗忘；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":8,"canonicalText":"父母惡之，懼而無怨；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":9,"canonicalText":"父母有過，諫而不逆；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-10","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":10,"canonicalText":"父母既沒，必求仁者之粟以祀之。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-11","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":11,"canonicalText":"此之謂禮終。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-33_s-12","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-33","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":1,"canonicalText":"樂正子春下堂而傷其足，數月不出，猶有憂色。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":2,"canonicalText":"門弟子曰：「夫子之足瘳矣，數月不出，猶有憂色，何也？","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":3,"canonicalText":"」樂正子春曰：「善如爾之問也！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":4,"canonicalText":"善如爾之問也！","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":5,"canonicalText":"吾聞諸曾子，曾子聞諸夫子曰：『天之所生，地之所養，無人為大。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":6,"canonicalText":"』父母全而生之，子全而歸之，可謂孝矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":7,"canonicalText":"不虧其體，不辱其身，可謂全矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-8","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":8,"canonicalText":"故君子頃步而弗敢忘孝也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-9","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":9,"canonicalText":"今予忘孝之道，予是以有憂色也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-10","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":10,"canonicalText":"壹舉足而不敢忘父母，壹出言而不敢忘父母。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-11","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":11,"canonicalText":"壹舉足而不敢忘父母，是故道而不徑，舟而不遊，不敢以先父母之遺體行殆。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-12","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":12,"canonicalText":"壹出言而不敢忘父母，是故惡言不出於口，忿言不反於身。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-13","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":13,"canonicalText":"不辱其身，不羞其親，可謂孝矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-34_s-14","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-34","order":14,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-35_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-35","order":1,"canonicalText":"昔者，有虞氏貴德而尚齒，夏后氏貴爵而尚齒，殷人貴富而尚齒，周人貴親而尚齒。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-35_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-35","order":2,"canonicalText":"虞夏殷周，天下之盛王也，未有遺年者。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-35_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-35","order":3,"canonicalText":"年之貴乎天下，久矣；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-35_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-35","order":4,"canonicalText":"次乎事親也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-36_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-36","order":1,"canonicalText":"是故朝廷同爵則尚齒。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-36_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-36","order":2,"canonicalText":"七十杖於朝，君問則席。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-36_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-36","order":3,"canonicalText":"八十不俟朝，君問則就之，而弟達乎朝廷矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-37_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-37","order":1,"canonicalText":"行，肩而不併，不錯則隨。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-37_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-37","order":2,"canonicalText":"見老者，則車徒闢；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-37_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-37","order":3,"canonicalText":"斑白者不以其任行乎道路，而弟達乎道路矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-37_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-37","order":4,"canonicalText":"居鄉以齒，而老窮不遺，強不犯弱，眾不暴寡，而弟達乎州巷矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-38_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-38","order":1,"canonicalText":"古之道，五十不為甸徒，頒禽隆諸長者，而弟達乎蒐狩矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-38_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-38","order":2,"canonicalText":"軍旅什伍，同爵則尚齒，而弟達乎軍旅矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-39_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-39","order":1,"canonicalText":"孝弟發諸朝廷，行乎道路，至乎州巷，放乎蒐狩，修乎軍旅，眾以義死之，而弗敢犯也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":1,"canonicalText":"祀乎明堂，所以教諸侯之孝也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":2,"canonicalText":"食三老五更於大學，所以教諸侯之弟也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":3,"canonicalText":"祀先賢於西學，所以教諸侯之德也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":4,"canonicalText":"耕藉，所以教諸侯之養也；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":5,"canonicalText":"朝覲，所以教諸侯之臣也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-40_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-40","order":6,"canonicalText":"五者，天下之大教也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-41_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-41","order":1,"canonicalText":"食三老五更於大學，天子袒而割牲，執醬而饋，執爵而酳，冕而總幹，所以教諸侯之弟也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-41_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-41","order":2,"canonicalText":"是故，鄉里有齒，而老窮不遺，強不犯弱，眾不暴寡，此由大學來者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-41_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-41","order":3,"canonicalText":"天子設四學，當入學，而大子齒。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-42_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-42","order":1,"canonicalText":"天子巡守，諸侯待於竟。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-42_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-42","order":2,"canonicalText":"天子先見百年者。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-42_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-42","order":3,"canonicalText":"八、十九十者東行，西行者弗敢過；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-42_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-42","order":4,"canonicalText":"西行，東行者弗敢過。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-42_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-42","order":5,"canonicalText":"欲言政者，君就之可也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-43_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-43","order":1,"canonicalText":"壹命齒於鄉里，再命齒於族，三命不齒；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-43_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-43","order":2,"canonicalText":"族有七十者，弗敢先。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-43_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-43","order":3,"canonicalText":"七十者，不有大故不入朝；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-43_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-43","order":4,"canonicalText":"若有大故而入，君必與之揖讓，而後及爵者。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":1,"canonicalText":"天子有善，讓德於天；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":2,"canonicalText":"諸侯有善，歸諸天子；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":3,"canonicalText":"卿大夫有善，薦於諸侯；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":4,"canonicalText":"士、庶人有善，本諸父母，存諸長老；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":5,"canonicalText":"祿爵慶賞，成諸宗廟；","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-44_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-44","order":6,"canonicalText":"所以示順也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-45_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-45","order":1,"canonicalText":"昔者，聖人建陰陽天地之情，立以為《易》。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-45_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-45","order":2,"canonicalText":"易抱龜南面，天子卷冕北面，雖有明知之心，必進斷其志焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-45_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-45","order":3,"canonicalText":"示不敢專，以尊天也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-45_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-45","order":4,"canonicalText":"善則稱人，過則稱己。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-45_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-45","order":5,"canonicalText":"教不伐以尊賢也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":1,"canonicalText":"孝子將祭祀，必有齊莊之心以慮事，以具服物，以修宮室，以治百事。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-2","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":2,"canonicalText":"及祭之日，顏色必溫，行必恐，如懼不及愛然。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-3","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":3,"canonicalText":"其奠之也，容貌必溫，身必詘，如語焉而未之然。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-4","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":4,"canonicalText":"宿者皆出，其立卑靜以正，如將弗見然。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-5","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":5,"canonicalText":"及祭之後，陶陶遂遂，如將復入然。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-6","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":6,"canonicalText":"是故，愨善不違身，耳目不違心，思慮不違親。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-46_s-7","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-46","order":7,"canonicalText":"結諸心，形諸色，而術省之，孝子之志也。","chunks":[],"tags":[]},{"id":"li-ji_ch-24_p-47_s-1","workId":"li-ji","chapterId":"li-ji_ch-24","passageId":"li-ji_ch-24_p-47","order":1,"canonicalText":"建國之神位：右社稷，而左宗廟。","chunks":[],"tags":[]}]}');export{i as default};
